import { describe, expect, it } from 'vitest';

import {
  expectError,
  jsonReply,
  patternDetail,
  patternHarness,
  readRequest,
  writeRequest,
} from './pattern-definition.test-support';

/**
 * BE03c 1298-1302: a response with an unmapped status or a message not generated by
 * the operation catalog is a contract failure -> scrubbed 500, never a caller refusal.
 */
const PROVIDER_FAULTS: readonly (readonly [string, number, unknown])[] = [
  ['PGRST202 function not found', 404, { code: 'PGRST202', message: 'x' }],
  ['PGRST301 bad service credential', 401, { code: 'PGRST301', message: 'x' }],
  [
    'SQLSTATE 42702 ambiguous column',
    400,
    { code: '42702', message: 'column reference "actor_id" is ambiguous' },
  ],
  ['SQLSTATE 42501 insufficient privilege', 403, { code: '42501' }],
  [
    'SQLSTATE 40001 engine serialization failure',
    409,
    { code: '40001', message: 'could not serialize access' },
  ],
  ['payload without any code', 404, { message: 'NOT_FOUND' }],
  ['unsupported 4xx status', 418, { code: 'PGRST999' }],
  ['array payload', 400, ['NOT_FOUND']],
  ['string payload', 404, 'NOT_FOUND'],
];
const operations = [
  { name: 'create', request: writeRequest },
  { name: 'latest', request: readRequest },
] as const;

describe.each(operations)(
  'pattern definition $name: provider 4xx without a product token',
  (operation) => {
    it.each(PROVIDER_FAULTS)(
      'scrubs %s to 500 INTERNAL_ERROR',
      async (_name, status, payload) => {
        const harness = patternHarness({
          reply: () => jsonReply(payload, status),
        });
        const error = await expectError(
          await harness.send(operation.request()),
          500,
          'INTERNAL_ERROR',
        );
        expect(error.details).toEqual({});
      },
    );

    it.each([
      ['structured NOT_FOUND', 404, { code: 'NOT_FOUND' }],
      ['P0001 NOT_FOUND', 400, { code: 'P0001', message: 'NOT_FOUND' }],
    ] as const)(
      'keeps the product answer for %s',
      async (_name, status, payload) => {
        const harness = patternHarness({
          reply: () => jsonReply(payload, status),
        });
        await expectError(
          await harness.send(operation.request()),
          404,
          'COMPOSITION_NOT_FOUND',
        );
      },
    );
  },
);

describe('pattern definition fault guard keeps the success path', () => {
  it('still answers a valid latest read', async () => {
    const harness = patternHarness({
      reply: () => jsonReply(patternDetail()),
    });
    expect((await harness.send(readRequest())).status).toBe(200);
  });
});

describe.each(operations)(
  'pattern definition $name: a response-contract failure is a retryable 502',
  (operation) => {
    it('answers a malformed 2xx body as 502 with retryable true (BE00 172)', async () => {
      const harness = patternHarness({ reply: () => jsonReply({ bad: true }) });
      const error = await expectError(
        await harness.send(operation.request()),
        502,
        'DEPENDENCY_UNAVAILABLE',
      );
      expect(error.details).toEqual({
        dependencyClass: 'cms_composition',
        retryable: true,
      });
    });
  },
);
